<?php
namespace App\Http\Controllers; use App\Models\Brand; use Illuminate\Http\Request; use Illuminate\Support\Str;
class BrandController extends Controller {public function index(Request $r){$q=$r->string('q')->toString();$brands=Brand::when($q,fn($x)=>$x->where('name','like',"%$q%"))->orderBy('name')->paginate(15)->withQueryString();return view('admin.brands.index',compact('brands','q'));}public function create(){return view('admin.brands.form',['brand'=>new Brand]);}public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:100','slug'=>'nullable|string|max:150|unique:brands,slug']);$d['slug']=$d['slug']?:Str::slug($d['name']);Brand::create($d);return redirect()->route('admin.brands.index')->with('success','Brand created.');}public function edit(Brand $brand){return view('admin.brands.form',compact('brand'));}public function update(Request $r,Brand $brand){$d=$r->validate(['name'=>'required|string|max:100','slug'=>'nullable|string|max:150|unique:brands,slug,'.$brand->brand_id.',brand_id']);$d['slug']=$d['slug']?:Str::slug($d['name']);$brand->update($d);return redirect()->route('admin.brands.index')->with('success','Brand updated.');}public function destroy(Brand $brand){if($brand->products()->exists())return back()->with('error','Brand is used by products.');$brand->delete();return back()->with('success','Brand deleted.');}}
